function validate([nums, x]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each price is a whole number from 1 to 10^9.';
  if (!Number.isInteger(x) || x < 1 || x > 1000000000) return 'x is a whole number from 1 to 10^9.';
  return null;
}

