function minCost(nums, x) {
  const n = nums.length;
  const cheapest = nums.slice();
  let answer = nums.reduce((sum, cost) => sum + cost, 0);

  for (let shifts = 1; shifts < n; shifts++) {
    let total = shifts * x;
    for (let type = 0; type < n; type++) {
      const holder = (type - shifts + n) % n;
      cheapest[type] = Math.min(cheapest[type], nums[holder]);
      total += cheapest[type];
    }
    answer = Math.min(answer, total);
  }
  return answer;
}

