function minCost(nums, x) {
  const n = nums.length;
  let best = Infinity;
  // With k shifts in total, the chocolates at indices i..i+k (cyclically) each get a turn at one type.
  for (let k = 0; k <= n; k++) {
    let total = k * x;
    for (let i = 0; i < n; i++) {
      let low = Infinity;
      for (let j = 0; j <= k; j++) low = Math.min(low, nums[(i + j) % n]);
      total += low;
    }
    best = Math.min(best, total);
  }
  return best;
}

