function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(900, 1000);
    const top = rand() < 0.5 ? 1000000000 : 1000;
    const nums = Array.from({ length: n }, () => int(1, top));
    const x = rand() < 0.5 ? int(1, 1000) : int(1, 1000000000);
    return [nums, x];
  }
  const n = int(1, 7);
  const top = rand() < 0.15 ? 1000000000 : int(1, 30);
  const nums = Array.from({ length: n }, () => int(1, top));
  const x = rand() < 0.1 ? int(1, 1000000000) : int(1, 20);
  return [nums, x];
}
